import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';

function StatsChart({ tasks }) {
  if (tasks.length === 0) return null;

  const COLORS = ['#64ffda', '#00d2ff', '#ffd700', '#ff6b6b', '#6a5acd'];

  // Data for Completion Status
  const completionData = [
    { name: 'Completed', value: tasks.filter(t => t.completed).length },
    { name: 'Pending', value: tasks.filter(t => !t.completed).length }
  ].filter(d => d.value > 0);

  // Data for Categories
  const categories = [...new Set(tasks.map(t => t.category))];
  const categoryData = categories.map(cat => ({
    name: cat,
    value: tasks.filter(t => t.category === cat).length
  }));

  return (
    <div className="chart-container">
      <h3 className="chart-title">Dashboard Overview</h3>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '2rem', justifyContent: 'center' }}>
        <div style={{ flex: '1 1 300px', minHeight: '300px' }}>
          <p style={{ textAlign: 'center', color: '#8892b0', marginBottom: '1rem' }}>Task Completion</p>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={completionData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
              >
                <Cell fill="#64ffda" />
                <Cell fill="rgba(255, 107, 107, 0.5)" />
              </Pie>
              <Tooltip
                contentStyle={{ background: '#112240', border: '1px solid #1d2d50', borderRadius: '10px', color: '#ccd6f6' }}
              />
              <Legend verticalAlign="bottom" height={36} />
            </PieChart>
          </ResponsiveContainer>
        </div>
        <div style={{ flex: '1 1 300px', minHeight: '300px' }}>
          <p style={{ textAlign: 'center', color: '#8892b0', marginBottom: '1rem' }}>Categories</p>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={categoryData}
                cx="50%"
                cy="50%"
                outerRadius={80}
                dataKey="value"
              >
                {categoryData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip
                contentStyle={{ background: '#112240', border: '1px solid #1d2d50', borderRadius: '10px', color: '#ccd6f6' }}
              />
              <Legend verticalAlign="bottom" height={36} />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}

export default StatsChart;
